using Microsoft.AspNetCore.Authorization; using Microsoft.AspNetCore.Mvc; using Microsoft.EntityFrameworkCore; using RaceDay.Api.Data; using RaceDay.Api.Dtos; using RaceDay.Api.Models;
namespace RaceDay.Api.Controllers;
[Authorize,Route("api")]
public sealed class EnrolmentsController(RaceDayContext db):ApiControllerBase {
 /// <summary>Enrols the authenticated participant into a category.</summary>
 [Authorize(Roles="Participant"),HttpPost("categories/{id:int}/enrolments")] public async Task<IActionResult> Create(int id){var c=await db.Categories.Include(x=>x.Enrolments).SingleOrDefaultAsync(x=>x.CategoryId==id);if(c is null)return NotFound();if(c.Enrolments.Count>=c.MaxParticipants)return Conflict(new{message="Category is full."});if(c.Enrolments.Any(x=>x.ParticipantId==CurrentUserId))return Conflict(new{message="Already enrolled in this category."});var e=new Enrolment{CategoryId=id,ParticipantId=CurrentUserId};db.Enrolments.Add(e);await db.SaveChangesAsync();return Created($"/api/enrolments/{e.EnrolmentId}",new{e.EnrolmentId,e.ParticipantId,e.CategoryId,e.EnrolmentDate,e.Status});}
 /// <summary>Lists the current participant's enrolments.</summary>
 [Authorize(Roles="Participant"),HttpGet("users/me/enrolments")] public async Task<IActionResult> Mine()=>Ok(await db.Enrolments.Where(x=>x.ParticipantId==CurrentUserId).Select(x=>new{x.EnrolmentId,x.CategoryId,Category=x.Category!.CategoryName,Event=x.Category!.Event!.EventName,x.EnrolmentDate,x.Status}).ToListAsync());
 /// <summary>Cancels the current participant's own enrolment.</summary>
 [Authorize(Roles="Participant"),HttpDelete("enrolments/{id:int}")] public async Task<IActionResult> Delete(int id){var e=await db.Enrolments.FindAsync(id);if(e is null)return NotFound();if(e.ParticipantId!=CurrentUserId)return Forbid();if(await db.Results.AnyAsync(x=>x.EnrolmentId==id))return Conflict(new{message="An enrolment with a recorded result cannot be cancelled."});db.Enrolments.Remove(e);await db.SaveChangesAsync();return NoContent();}
 /// <summary>Captures a result for an enrolment belonging to an event owned by the organiser.</summary>
 [Authorize(Roles="Organiser"),HttpPost("enrolments/{id:int}/results")] public async Task<IActionResult> AddResult(int id,ResultRequest r){var e=await db.Enrolments.Include(x=>x.Category).ThenInclude(x=>x!.Event).SingleOrDefaultAsync(x=>x.EnrolmentId==id);if(e is null)return NotFound();if(e.Category!.Event!.OrganiserId!=CurrentUserId)return Forbid();if(await db.Results.AnyAsync(x=>x.EnrolmentId==id))return Conflict(new{message="A result has already been recorded."});if(r.FinishTime<=TimeSpan.Zero)return BadRequest(new{message="Finish time must be greater than zero."});var result=new Result{EnrolmentId=id,FinishTime=r.FinishTime,Position=r.Position,RecordedByUserId=CurrentUserId};db.Results.Add(result);await db.SaveChangesAsync();return Created($"/api/enrolments/{id}/results",result);}
 /// <summary>Returns results belonging to the current participant.</summary>
 [Authorize(Roles="Participant"),HttpGet("users/me/results")] public async Task<IActionResult> MyResults()=>Ok(await db.Results.Where(x=>x.Enrolment!.ParticipantId==CurrentUserId).Select(x=>new{x.ResultId,x.EnrolmentId,Event=x.Enrolment!.Category!.Event!.EventName,Category=x.Enrolment!.Category!.CategoryName,x.FinishTime,x.Position,x.RecordedAt}).ToListAsync());
}
